using Astronomy.MediaFactory.Core.DocumentaryBlueprint;
namespace Astronomy.MediaFactory.Tests.DocumentaryBlueprint;
public sealed class DocumentaryMediaPipelineDependencyTests
{
 [Fact] public void Graph_is_complete_ordered_unique_and_acyclic(){var p=DocumentaryMediaPipelineFixture.Plan(DocumentaryMediaPipelineFixture.Orion());Assert.Equal(Enumerable.Range(0,p.DependencyCount),p.AssetDependencies.Select(x=>x.Sequence));Assert.Equal(p.DependencyCount,p.AssetDependencies.Select(x=>x.DependencyId).Distinct().Count());var ids=p.AssetPlans.Select(x=>x.AssetId).ToHashSet();Assert.All(p.AssetDependencies,x=>{Assert.Contains(x.SourceAssetId,ids);Assert.Contains(x.TargetAssetId,ids);Assert.NotEqual(x.SourceAssetId,x.TargetAssetId);});Assert.All(p.AssetPlans.Where(x=>x.AssetType is DocumentaryMediaAssetType.VisualImage or DocumentaryMediaAssetType.SkySimulationImage or DocumentaryMediaAssetType.StarChartImage or DocumentaryMediaAssetType.TelescopeViewImage or DocumentaryMediaAssetType.ScientificDiagramImage or DocumentaryMediaAssetType.HistoricalIllustrationImage or DocumentaryMediaAssetType.NarrationAudio),x=>Assert.Empty(x.Dependencies));DocumentaryMediaPipelineValidator.ValidateExecutionPlan(p);}
 [Fact] public void Corrupt_endpoint_is_rejected_as_dependency_mismatch(){var p=DocumentaryMediaPipelineFixture.Plan(DocumentaryMediaPipelineFixture.Orion());var bad=p.AssetDependencies.ToArray();bad[0]=bad[0] with{SourceAssetId="missing"};var corrupt=p with{AssetDependencies=bad};var ex=Assert.Throws<ArgumentException>(()=>DocumentaryMediaPipelineValidator.ValidateExecutionPlan(corrupt));Assert.Equal(nameof(DocumentaryMediaPipelineRejectionReason.AssetDependencyMismatch),ex.Message);}
}
